"""Local presentation assets for the demonstration console."""

CSS = '''
:root{font-family:Inter,Segoe UI,system-ui,sans-serif;color:#193445;background:#f3f6f6;font-size:15px}
*{box-sizing:border-box}body{margin:0}a{color:#087a78;text-decoration:none}button,input,select,textarea{font:inherit}
header{background:#102d3b;color:white;padding:24px max(24px,calc((100vw - 1400px)/2));display:flex;align-items:center;justify-content:space-between;gap:20px}header small{color:#8ac9c5;font-size:11px;letter-spacing:.16em}h1{font-size:23px;font-weight:600;margin:5px 0}header p{color:#c1d3da;margin:0;font-size:13px}header button{background:#244755;color:white;border:1px solid #47636f}
main{max-width:1400px;margin:auto;padding:30px 24px}.workspace{display:grid;grid-template-columns:340px minmax(0,1fr);gap:24px;align-items:start}.settings{display:grid;gap:16px}.card{background:white;border:1px solid #e0e8e9;border-radius:18px;box-shadow:0 5px 20px #15354305;overflow:hidden}.settings>details{padding:20px}.settings summary{cursor:pointer;font-weight:600;font-size:16px}.settings summary small{display:block;font-weight:400;font-size:12px;color:#627987;margin:7px 0 0 19px}h2{font-size:18px;margin:0}p{line-height:1.6}.muted,.hint{color:#627987;font-size:13px}.hint{margin:8px 0}.badge{display:inline-block;background:#e7f4ef;color:#25644e;border-radius:20px;padding:5px 10px;font-size:12px}.notice{padding:14px 18px;border:1px solid #c7e3db;background:#e9f6f0;border-radius:12px;margin:0 0 20px}.error{background:#fff2ed;border-color:#edcbbc;color:#8b3925}
label{display:block;margin:17px 0 6px;font-size:13px;font-weight:500}input,select,textarea{width:100%;border:1px solid #cbd9de;background:#fbfdfd;color:#193445;padding:11px 12px;border-radius:9px;min-width:0}input[type=file]{padding:15px 10px;font-size:12px;border-style:dashed;background:#f4faf9}input[type=file]::file-selector-button{border:0;border-radius:6px;padding:7px;background:#dceeea;color:#235a56;margin-right:7px}button{border:0;border-radius:9px;padding:11px 17px;background:#087f7c;color:white;cursor:pointer;font-weight:600;font-size:13px}form>button{margin-top:15px}button.secondary{background:#eef4f5;color:#315565}button:disabled{opacity:.5;cursor:wait}:focus-visible{outline:3px solid #69b8b5;outline-offset:3px}.advanced{margin-top:18px;border-top:1px solid #e1e9eb;padding-top:15px}.advanced summary{font-size:13px;color:#56717d}.advanced-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 10px}.file-list{padding-left:18px;font-size:12px;color:#47626e;overflow-wrap:anywhere}.chat-top{padding:22px 26px;border-bottom:1px solid #e5ecee;display:flex;justify-content:space-between;align-items:center;gap:12px}.chat-top p{margin:5px 0 0}.chat-top form{margin:0}.chat-top button{margin:0}.history{padding:12px 26px;border-bottom:1px solid #e5ecee;font-size:13px}.history summary{cursor:pointer;color:#607781}.history ul{padding-left:20px;max-height:140px;overflow:auto}.transcript{height:clamp(320px,48vh,640px);overflow-y:auto;padding:28px;display:flex;flex-direction:column;gap:18px;scroll-behavior:smooth}.empty{margin:auto;text-align:center;max-width:360px}.empty .mark{display:inline-grid;place-items:center;width:56px;height:56px;border-radius:18px;background:#e4f3ef;color:#087f7c;font-size:27px}.empty h3{font-size:21px;font-weight:600;margin-bottom:6px}.bubble{max-width:88%;align-self:flex-start}.bubble.user{align-self:flex-end}.bubble .role{font-size:11px;font-weight:600;color:#657f8b;margin-bottom:6px}.bubble.user .role{text-align:right}.bubble .text{background:#f0f5f5;border:1px solid #e5eded;border-radius:4px 15px 15px;padding:14px 17px;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.65}.bubble.user .text{background:#127d7a;color:white;border-color:#127d7a;border-radius:15px 4px 15px 15px}.composer{padding:18px 24px;background:#fbfdfd;border-top:1px solid #e1eaec}.composer form{display:flex;gap:12px;align-items:end}.composer textarea{resize:vertical;min-height:76px;max-height:220px;background:white}.composer label{position:absolute;width:1px;height:1px;overflow:hidden}.composer button{margin:0;min-height:46px}.composer .hint{font-size:11px;margin-bottom:0}.chat-error{margin:0 24px 15px}.login{max-width:420px;margin:6vh auto;padding:32px}.login h2{font-size:25px}.login button{width:100%}.login .brand{color:#087f7c;font-size:12px;letter-spacing:.12em}#operation-status:empty{display:none}#operation-status{font-size:13px;color:#486975;margin:12px 24px}
@media(max-width:850px){.workspace{grid-template-columns:1fr}.settings{grid-template-columns:repeat(3,minmax(0,1fr))}.settings>details{padding:15px}.settings summary{font-size:14px}.advanced-grid{grid-template-columns:1fr}header{padding:20px 24px}.transcript{height:48vh}}
@media(max-width:600px){main{padding:18px 12px}.settings{grid-template-columns:1fr;gap:10px}.settings>details{padding:16px}.chat-top,.history{padding:16px}.transcript{padding:18px;height:48vh;min-height:300px}.composer{padding:14px}.composer form{gap:8px}.bubble{max-width:94%}header{padding:18px}h1{font-size:19px}header p{display:none}.login{margin:4vh auto;padding:25px}.chat-top h2{font-size:16px}}
'''

JS = '''
document.querySelectorAll('input[type=file]').forEach(input=>input.addEventListener('change',()=>{
 const list=document.getElementById('file-list');list.replaceChildren();
 Array.from(input.files).forEach(file=>{const li=document.createElement('li');li.textContent=file.name;list.appendChild(li)});
}));
const provider=document.getElementById('provider');
if(provider)provider.addEventListener('change',()=>{window.location.assign('/?provider='+encodeURIComponent(provider.value)+'#ai')});
document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',event=>{
 if(form.dataset.busy){event.preventDefault();return}form.dataset.busy='1';
 const status=document.getElementById('operation-status');if(status)status.textContent=form.action.endsWith('/chat/send')?'Respondendo…':'Processando…';
 form.querySelectorAll('button').forEach(button=>button.disabled=true);
}));
const message=document.getElementById('message');
if(message)message.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();message.form.requestSubmit()}});
const transcript=document.getElementById('transcript');if(transcript)transcript.scrollTop=transcript.scrollHeight;
if(matchMedia('(max-width:600px)').matches)document.querySelectorAll('.settings>details').forEach(detail=>detail.open=false);
window.addEventListener('pageshow',()=>document.querySelectorAll('form[data-busy]').forEach(form=>{delete form.dataset.busy;form.querySelectorAll('button').forEach(button=>button.disabled=false)}));
'''
